


function out = fig33(resultFile)
% ANALYZE_COLLISION_CONVERSION_DATA
% -------------------------------------------------------------------------
% Numerical-data post-processing for the two-component collision generated by
%   pengzhuang_twocomponent_pump_g11_g22_g12(3).m
%
% Main diagnostics
%   1. Robust collision-time selection from C12(t), center separation,
%      and soliton widths.
%   2. Instantaneous Bloch-band populations of component 2, obtained by a
%      cell-resolved Bloch transform.  No nonlinear-template
%      orthogonalization is used.
%   3. Core fraction, radiation fraction, mean momentum, and nodal count.
%   4. Frozen nonlinear ground-like/excited-like branches before, during,
%      and after the collision.  Their fidelities are reported separately;
%      they are NOT interpreted as mutually exclusive populations.
%   5. Bare and local-periodic mean-field band diagrams at the three
%      selected times.
%   6. E12: interaction energy in a window following the component-2 core.
%      E12Full retains the full-domain interaction energy for comparison.
%
% Usage A: run directly after the original simulation
%   out = fig33;
%
% Usage B: analyze a saved MAT file
%   out = fig33('xxx_Result.mat');
%
% Plot the saved results afterwards with
%   plot_collision_conversion_results('collision_conversion_revised_analysis.mat');
%
% Required variables
%   x, tdata, udata1, udata2, lat
%
% Recommended additional variables
%   k, wt, psi, psiGround, psi2_0
%
% IMPORTANT
%   The instantaneous Bloch populations refer to the BARE periodic lattice
%   H0(t) = -1/2 d_xx + V(x,t).  They directly test interband transfer.
%
%   The "local effective bands" periodically repeat one cell of
%   V + g12|psi1|^2 + g22|psi2|^2 around component 2.  They are only a
%   local-periodic approximation because the collision density breaks
%   translation symmetry.
% -------------------------------------------------------------------------

if nargin < 1
    resultFile = '';
end

fprintf('\nRunning %s from\n  %s\n',mfilename,mfilename('fullpath'));
fprintf('Version: 2026-10-12-tracked-coupling-energy\n');

%% ============================= USER SETTINGS ============================
cfg.manualTimes = [];             % [tBefore,tCollision,tAfter], [] = auto
cfg.smoothFrames = 11;            % smoothing of C12 for collision detection
cfg.majorPeakFraction = 0.60;     % first peak above this fraction of max
cfg.collisionClusterFraction = 0.10;
cfg.quietOverlapFraction = 0.035;
cfg.separationWidthFactor = 1.6;
cfg.selectionMarginFrames = 5;
cfg.afterHoldFrames = 5;

% Instantaneous Bloch projection
cfg.bandWindowCells = 20;         % integer number of lattice cells in crop
cfg.nBandsTrack = 5;              % plot first several bands
cfg.bandStride = 1;               % 1 = every saved frame
cfg.nBandsReconstruct = 3;        % selected-time real-space reconstructions

% Core diagnostics
cfg.coreHalfWidth = 4.0;
cfg.nodeAmplitudeFraction = 0.10;

% Coupling energy: follow the actual component-2 soliton, including collision.
cfg.couplingWindow = [1.0,1.0];   % 移动窗口：[轨迹左宽,轨迹右宽]
cfg.couplingSearchHalfWidth = 1.5;
cfg.couplingCenterHalfWidth = 0.75;
cfg.couplingReacquireRatio = 0.35;
cfg.couplingStartX = [];          % 空：第二组分初始最强峰

% Frozen nonlinear branches at before/collision/after
cfg.solveFrozenBranches = true;
cfg.imagDt = 1e-3;
cfg.imagMaxIter = 60000;
cfg.imagTol = 1e-10;
cfg.newtonTol = 1e-8;
cfg.newtonMaxIter = 70;
cfg.lineSearchMax = 18;
cfg.excitedNodeExcess = 1;        % excited branch needs at least this many
                                  % additional core nodes relative to ground

% Instantaneous band diagrams
cfg.bandPlotNk = 181;
cfg.bandPlotCount = 4;

% Output
cfg.savePrefix = 'collision_conversion_revised';
cfg.saveResults = true;

%% =============================== LOAD DATA ===============================
D = load_input_data(resultFile);
required = {'x','tdata','udata1','udata2','lat'};
for jj = 1:numel(required)
    if ~isfield(D,required{jj})
        error('Missing required variable: %s',required{jj});
    end
end

x = D.x(:);
t = D.tdata(:).';
u1all = D.udata1;
u2all = D.udata2;
lat = D.lat;

N = numel(x);
Nt = numel(t);
if size(u1all,1) ~= N && size(u1all,2) == N
    u1all = u1all.';
end
if size(u2all,1) ~= N && size(u2all,2) == N
    u2all = u2all.';
end
if size(u1all,1) ~= N || size(u2all,1) ~= N
    error('udata1 and udata2 must have length(x) rows.');
end
if size(u1all,2) ~= Nt || size(u2all,2) ~= Nt
    error('Wave-function frame number must equal length(tdata).');
end

dx = mean(diff(x));
L = N*dx;
if isfield(D,'wt')
    wt = D.wt(:);
else
    wt = dx*ones(N,1);
end
if isfield(D,'k')
    k = D.k(:);
else
    if mod(N,2) ~= 0
        error('An even spatial grid is required when k is not supplied.');
    end
    k = [0:N/2-1,-N/2:-1].'*(2*pi/L);
end
if ~isfield(lat,'a')
    lat.a = 1;
end
if ~isfield(lat,'g11') || ~isfield(lat,'g22') || ~isfield(lat,'g12')
    error('lat.g11, lat.g22, and lat.g12 are required.');
end

Npc = round(lat.a/dx);
if abs(Npc*dx-lat.a) > 1e-10
    error('The grid must satisfy a/dx = integer. Current a/dx = %.12g.',lat.a/dx);
end
maxFullCells = floor(N/Npc);
if cfg.bandWindowCells > maxFullCells
    cfg.bandWindowCells = maxFullCells;
    warning('bandWindowCells reduced to %d.',cfg.bandWindowCells);
end
if cfg.bandWindowCells < 4
    error('At least four full cells are needed for Bloch projection.');
end

rho1 = abs(u1all).^2;
rho2 = abs(u2all).^2;
N1 = sum(wt.*rho1,1);
N2 = sum(wt.*rho2,1);

%% ======================= CENTERS, WIDTHS, COLLISION ======================
xc1 = zeros(1,Nt);
xc2 = zeros(1,Nt);
w1 = zeros(1,Nt);
w2 = zeros(1,Nt);
C12 = zeros(1,Nt);
E12 = zeros(1,Nt);
C12core = zeros(1,Nt);
E12Full = zeros(1,Nt);
p2mean = zeros(1,Nt);
coreFraction = zeros(1,Nt);
coreNodeCount = zeros(1,Nt);

% 局部主峰及其附近质心追踪；不用会被远处辐射拖动的全局质心。
[xcCouple,couplingReacquired] = track_coupling_core(x,t,rho2,wt,cfg);
couplingLeft = max(x(1)-dx/2,xcCouple-cfg.couplingWindow(1));
couplingRight = min(x(end)+dx/2,xcCouple+cfg.couplingWindow(2));
% 网格边缘按覆盖比例计权，减少窗口跨网格时的积分跳动。
couplingWeight = max(0,min(x+dx/2,couplingRight)-max(x-dx/2,couplingLeft))/dx;
couplingWeight = min(1,couplingWeight);

for it = 1:Nt
    xc1(it) = density_center(x,rho1(:,it),wt);
    xc2(it) = density_center(x,rho2(:,it),wt);
    w1(it) = density_width(x,rho1(:,it),wt,xc1(it));
    w2(it) = density_width(x,rho2(:,it),wt,xc2(it));
    C12(it) = real(sum(wt.*rho1(:,it).*rho2(:,it)));
    C12core(it) = real(sum(wt.*couplingWeight(:,it).*rho1(:,it).*rho2(:,it)));
    E12(it) = lat.g12*C12core(it); % 局部耦合能，不归一化，不取绝对值
    E12Full(it) = lat.g12*C12(it);
    p2mean(it) = mean_momentum(u2all(:,it),k,wt);

    maskCore = abs(x-xc2(it)) <= cfg.coreHalfWidth;
    coreFraction(it) = real(sum(wt(maskCore).*rho2(maskCore,it))/(N2(it)+eps));
    uRest = remove_mean_flow(u2all(:,it),x,xc2(it),p2mean(it));
    coreNodeCount(it) = count_core_nodes(uRest,x,xc2(it), ...
        cfg.coreHalfWidth,cfg.nodeAmplitudeFraction);
end

separation = abs(xc2-xc1);
C12s = movmean(C12,max(1,cfg.smoothFrames));
idxSel = choose_collision_frames(t,C12s,separation,w1,w2,cfg);
ib = idxSel(1); ic = idxSel(2); ia = idxSel(3);
labels = {'before','collision','after'};

fprintf('\n================ Selected collision frames ================\n');
for js = 1:3
    ii = idxSel(js);
    fprintf('%-9s frame=%5d, t=%12.6g, C12=%10.5g, separation=%9.4g\n', ...
        labels{js},ii,t(ii),C12(ii),separation(ii));
end

%% ================= INSTANTANEOUS BARE BLOCH PROJECTION ==================
trackIdx = 1:cfg.bandStride:Nt;
Pband = NaN(cfg.nBandsTrack,Nt);
Phigher = NaN(1,Nt);
Poutside = NaN(1,Nt);
Pinside = NaN(1,Nt);
projectionClosure = NaN(1,Nt);

fprintf('\nComputing instantaneous Bloch-band populations...\n');
for jj = 1:numel(trackIdx)
    it = trackIdx(jj);
    Rb = bloch_project_component(u2all(:,it),x,t(it),lat,xc2(it),cfg,false);
    nb = min(cfg.nBandsTrack,numel(Rb.populationGlobal));
    Pband(1:nb,it) = Rb.populationGlobal(1:nb);
    Phigher(it) = Rb.higherGlobal;
    Poutside(it) = Rb.outsideSpatial;
    Pinside(it) = Rb.insideSpatial;
    projectionClosure(it) = sum(Rb.populationGlobal)+Rb.higherGlobal+Rb.outsideSpatial;
    if mod(jj,max(1,round(numel(trackIdx)/20))) == 0 || jj == numel(trackIdx)
        fprintf('  Bloch projection %5d / %5d\n',jj,numel(trackIdx));
    end
end

% Selected-time reconstruction of the first few bare bands.
% Use a cell array deliberately.  MATLAB struct-array assignment requires
% absolutely identical field sets and field order; a cell array removes
% that fragile requirement and is robust to optional diagnostic fields.
BandProjection = cell(1,3);
for js = 1:3
    ii = idxSel(js);
    BandProjection{js} = bloch_project_component( ...
        u2all(:,ii),x,t(ii),lat,xc2(ii),cfg,true);
end

%% ====================== FROZEN NONLINEAR BRANCHES =======================
Frozen = repmat(empty_frozen_result(),1,3);
if cfg.solveFrozenBranches
    fprintf('\nSolving frozen nonlinear branches...\n');
    Tmat = build_kinetic_matrix(k);

    psiExcitedRef = [];
    if isfield(D,'psi')
        psiExcitedRef = D.psi(:);
    elseif isfield(D,'psi2_0')
        psiExcitedRef = D.psi2_0(:);
    else
        psiExcitedRef = u2all(:,1);
    end
    xcExcitedRef = density_center(x,abs(psiExcitedRef).^2,wt);

    previousExcited = [];
    for js = 1:3
        ii = idxSel(js);
        u1 = u1all(:,ii);
        u2 = u2all(:,ii);
        V = external_potential(x,t(ii),lat);
        Vbase = V+lat.g12*abs(u1).^2;
        targetN = real(sum(wt.*abs(u2).^2));
        uRest = remove_mean_flow(u2,x,xc2(ii),p2mean(ii));

        fprintf('  %s, t=%.8g: frozen ground branch...\n',labels{js},t(ii));
        seedGround = abs(uRest);
        seedGround = normalize_to_norm(seedGround,targetN,wt);
        [phiG,infoG] = imaginary_time_fixed_norm(seedGround,Vbase,lat.g22, ...
            k,wt,targetN,cfg);

        groundNodes = count_core_nodes(phiG,x,density_center(x,abs(phiG).^2,wt), ...
            cfg.coreHalfWidth,cfg.nodeAmplitudeFraction);
        infoG.nodeCount = groundNodes;

        % Candidate excited seeds: shifted isolated excited state, actual
        % deboosted state, bare second-band reconstruction, and continuation.
        candidateSeeds = {};
        shiftedRef = fft_shift_state(psiExcitedRef,xc2(ii)-xcExcitedRef,k);
        candidateSeeds{end+1} = real_gauge_seed(shiftedRef); %#ok<AGROW>
        candidateSeeds{end+1} = real_gauge_seed(uRest); %#ok<AGROW>
        if size(BandProjection{js}.reconstruction,2) >= 2
            candidateSeeds{end+1} = real_gauge_seed( ...
                BandProjection{js}.reconstruction(:,2)); %#ok<AGROW>
        end
        if ~isempty(previousExcited)
            candidateSeeds{end+1} = previousExcited; %#ok<AGROW>
        end

        fprintf('  %s, t=%.8g: frozen excited branch (%d seeds)...\n', ...
            labels{js},t(ii),numel(candidateSeeds));
        [phiE,infoE] = best_excited_branch(candidateSeeds,uRest,Vbase,lat.g22, ...
            Tmat,k,wt,targetN,x,groundNodes,cfg);

        if infoE.valid
            previousExcited = phiE;
        end

        Fg = state_fidelity(phiG,uRest,wt);
        if infoE.valid
            Fe = state_fidelity(phiE,uRest,wt);
            Sge = state_fidelity(phiG,phiE,wt);
        else
            Fe = NaN;
            Sge = NaN;
        end

        Frozen(js).time = t(ii);
        Frozen(js).index = ii;
        Frozen(js).uRest = uRest;
        Frozen(js).ground = phiG;
        Frozen(js).excited = phiE;
        Frozen(js).Fg = Fg;
        Frozen(js).Fe = Fe;
        Frozen(js).Sge = Sge;
        Frozen(js).groundInfo = infoG;
        Frozen(js).excitedInfo = infoE;
        Frozen(js).currentResidual = frozen_current_residual(uRest,Vbase,lat.g22, ...
            k,wt);
        Frozen(js).currentEnergy = nonlinear_energy(uRest,Vbase,lat.g22,k,wt);
        Frozen(js).groundEnergy = nonlinear_energy(phiG,Vbase,lat.g22,k,wt);
        if infoE.valid
            Frozen(js).excitedEnergy = nonlinear_energy(phiE,Vbase,lat.g22,k,wt);
        else
            Frozen(js).excitedEnergy = NaN;
        end

        fprintf(['    Fg=%.5f, Fe=%.5f, |<g|e>|^2=%.5f, ', ...
                 'ground nodes=%d, excited nodes=%d, excited valid=%d\n'], ...
            Fg,Fe,Sge,infoG.nodeCount,infoE.nodeCount,infoE.valid);
    end
end

%% ==================== INSTANTANEOUS BAND DIAGRAMS =======================
% Store selected-time band diagrams in cells for the same robustness.
Bands = cell(1,3);
for js = 1:3
    ii = idxSel(js);
    Bands{js} = instantaneous_band_diagrams(x,t(ii),u1all(:,ii), ...
        u2all(:,ii),xc2(ii),lat,cfg);
end

fprintf('\n================ Band gaps ================\n');
fprintf('Delta12 = min_k E2 - max_k E1; Delta12 <= 0 indicates overlap.\n');
for js = 1:3
    fprintf('%-9s t=%10.5g: bare=% .6e, cross=% .6e, full=% .6e\n', ...
        labels{js},t(idxSel(js)),Bands{js}.gapBare, ...
        Bands{js}.gapCross,Bands{js}.gapFull);
end

%% ========================== NUMERICAL SUMMARY ===========================
fprintf('\n================ Conversion diagnostics ================\n');
for js = 1:3
    ii = idxSel(js);
    fprintf('\n%s, t=%.8g\n',upper(labels{js}),t(ii));
    for nb = 1:cfg.nBandsTrack
        fprintf('  bare band %d global weight = %.6f\n',nb,Pband(nb,ii));
    end
    fprintf('  higher-band weight          = %.6f\n',Phigher(ii));
    fprintf('  outside projection crop     = %.6f\n',Poutside(ii));
    fprintf('  core fraction               = %.6f\n',coreFraction(ii));
    fprintf('  core node count             = %d\n',coreNodeCount(ii));
    if cfg.solveFrozenBranches
        fprintf('  frozen ground fidelity Fg   = %.6f\n',Frozen(js).Fg);
        fprintf('  frozen excited fidelity Fe  = %.6f\n',Frozen(js).Fe);
        fprintf('  frozen branch overlap       = %.6f\n',Frozen(js).Sge);
        fprintf('  excited branch valid        = %d\n',Frozen(js).excitedInfo.valid);
    end
end

P1before = Pband(1,ib); P2before = Pband(2,ib);
P1after = Pband(1,ia);  P2after = Pband(2,ia);
linearBandTransfer = (P2before > P1before) && (P1after > P2after) && ...
                     (P1after-P1before > 0.10);
localGapClosure = Bands{2}.gapFull <= 0;
bareGapClosure = Bands{2}.gapBare <= 0;

fprintf('\nBare-band transfer criterion satisfied: %d\n',linearBandTransfer);
fprintf('Bare gap closes at collision:          %d\n',bareGapClosure);
fprintf('Local effective gap closes:            %d\n',localGapClosure);

if linearBandTransfer && ~bareGapClosure
    fprintf(['Interpretation: component 2 shows a genuine redistribution from the ', ...
        'second bare Bloch band toward the first band, while the bare gap remains ', ...
        'open.  The transfer is therefore caused by collision-induced nonadiabatic ', ...
        'coupling, not by overlap of the original linear bands.\n']);
elseif ~linearBandTransfer
    fprintf(['Interpretation: the data do not establish a clean second-to-first bare-band ', ...
        'transfer.  A ground-like central peak may coexist with higher-band content ', ...
        'and radiation.  Use the reported band weights and frozen fidelities rather ', ...
        'than the density profile alone.\n']);
end
if localGapClosure && ~bareGapClosure
    fprintf(['The local-periodic mean-field approximation shows an interaction-induced ', ...
        'gap closing.  This may facilitate transfer, but it is not an overlap of the ', ...
        'bare Bloch bands.\n']);
end

%% ================================ OUTPUT ================================
out = struct();
out.cfg = cfg;
out.x = x;
out.labels = labels;
out.t = t;
out.N1 = N1;
out.N2 = N2;
out.selectedU1 = u1all(:,idxSel);
out.selectedU2 = u2all(:,idxSel);
out.selectedRho1 = rho1(:,idxSel);
out.selectedRho2 = rho2(:,idxSel);
out.selectedXc2 = xc2(idxSel);
out.selectedIndex = idxSel;
out.selectedTime = t(idxSel);
out.C12 = C12;
out.C12smooth = C12s;
out.E12 = E12;
out.E12Core = E12;
out.E12Full = E12Full;
out.C12core = C12core;
out.xcCouple = xcCouple;
out.couplingLeft = couplingLeft;
out.couplingRight = couplingRight;
out.couplingWeight = couplingWeight;
out.couplingReacquired = couplingReacquired;
out.E12Definition = 'g12 * integral W(x,t)*|psi1(x,t)|^2*|psi2(x,t)|^2 dx';
out.E12WindowDefinition = 'Window follows the local core of component 2; all collision frames included.';
out.xc1 = xc1;
out.xc2 = xc2;
out.width1 = w1;
out.width2 = w2;
out.separation = separation;
out.p2mean = p2mean;
out.coreFraction = coreFraction;
out.coreNodeCount = coreNodeCount;
out.Pband = Pband;
out.Phigher = Phigher;
out.Poutside = Poutside;
out.Pinside = Pinside;
out.projectionClosure = projectionClosure;
out.BandProjection = BandProjection;
out.Frozen = Frozen;
out.Bands = Bands;
out.linearBandTransfer = linearBandTransfer;
out.bareGapClosure = bareGapClosure;
out.localGapClosure = localGapClosure;

if cfg.saveResults
    analysisFile = [cfg.savePrefix '_analysis.mat'];
    save(analysisFile,'out','-v7.3');
    T = table(t(:),C12(:),C12s(:),E12(:),xc1(:),xc2(:), ...
        separation(:),w1(:),w2(:),p2mean(:),coreFraction(:), ...
        coreNodeCount(:),Poutside(:),Phigher(:), ...
        'VariableNames',{'t','C12','C12smooth','E12','xc1','xc2', ...
        'separation','width1','width2','p2mean','coreFraction', ...
        'coreNodeCount','Poutside','Phigher'});
    for nb = 1:cfg.nBandsTrack
        T.(sprintf('Pband%d',nb)) = Pband(nb,:).';
    end
    T.E12Full = E12Full(:);
    T.C12core = C12core(:);
    T.xcCouple = xcCouple(:);
    T.couplingLeft = couplingLeft(:);
    T.couplingRight = couplingRight(:);
    T.couplingReacquired = couplingReacquired(:);
    writetable(T,[cfg.savePrefix '_timeseries.csv']);
    fprintf('\nAnalysis data saved to:\n  %s\n',analysisFile);
    fprintf('Plot the saved data with:\n');
    fprintf('  plot_collision_conversion_results(''%s'');\n',analysisFile);
end

end

%% ========================================================================
%% Local functions
%% ========================================================================
function [xc,reacquired] = track_coupling_core(x,t,rho,wt,cfg)
% 与核心能带投影采用相同的局部主峰/质心追踪方法。
if numel(cfg.couplingWindow)~=2 || any(~isfinite(cfg.couplingWindow)) || ...
        any(cfg.couplingWindow<=0)
    error('cfg.couplingWindow 必须为两个正有限数：[左宽,右宽]。');
end
if ~isscalar(cfg.couplingSearchHalfWidth) || ~isfinite(cfg.couplingSearchHalfWidth) || ...
        cfg.couplingSearchHalfWidth<=0 || ~isscalar(cfg.couplingCenterHalfWidth) || ...
        ~isfinite(cfg.couplingCenterHalfWidth) || cfg.couplingCenterHalfWidth<=0 || ...
        ~isscalar(cfg.couplingReacquireRatio) || ~isfinite(cfg.couplingReacquireRatio) || ...
        cfg.couplingReacquireRatio<=0 || cfg.couplingReacquireRatio>1
    error('追踪半宽须为正数，couplingReacquireRatio 须在 (0,1]。');
end
if ~isempty(cfg.couplingStartX) && (~isscalar(cfg.couplingStartX) || ...
        ~isfinite(cfg.couplingStartX))
    error('cfg.couplingStartX 应为空或一个有限位置。');
end
dx=x(2)-x(1); Nt=numel(t);
if dx<=0 || any(~isfinite(x)) || any(~isfinite(t)) || ...
        max(abs(diff(x)-dx))>1e-8*dx || any(diff(t)<=0) || ...
        numel(wt)~=numel(x) || any(~isfinite(wt)) || any(wt<=0) || ...
        any(~isfinite(rho(:)))
    error('轨迹追踪需要递增等距 x、递增 t、正积分权重和有限密度。');
end
xc=nan(1,Nt); reacquired=false(1,Nt);
for it=1:Nt
    [globalPeak,ig]=max(rho(:,it));
    if it==1
        prediction=cfg.couplingStartX;
    else
        prediction=xc(it-1);
        if it>2
            step=(xc(it-1)-xc(it-2))*(t(it)-t(it-1))/(t(it-1)-t(it-2));
            bound=cfg.couplingSearchHalfWidth/2;
            prediction=prediction+max(-bound,min(bound,step));
        end
        prediction=max(x(1),min(x(end),prediction));
    end
    if isempty(prediction), ids=(1:numel(x)).';
    else, ids=find(abs(x-prediction)<=cfg.couplingSearchHalfWidth); end
    if isempty(ids), error('第 %d 帧追踪窗口与网格没有交集。',it); end
    [localPeak,j]=max(rho(ids,it)); p=ids(j);
    if it>1 && localPeak<cfg.couplingReacquireRatio*globalPeak
        p=ig; reacquired(it)=true;
    end
    peak=x(p); h=cfg.couplingCenterHalfWidth;
    w=max(0,min(x+dx/2,peak+h)-max(x-dx/2,peak-h))/dx;
    mass=sum(wt.*w.*rho(:,it));
    if mass<=0, error('第 %d 帧第二组分主峰窗口为空。',it); end
    xc(it)=sum(x.*wt.*w.*rho(:,it))/mass;
end
end

function D = load_input_data(resultFile)
if ~isempty(resultFile)
    if ~isfile(resultFile)
        error('Cannot find result file: %s',resultFile);
    end
    D = load(resultFile);
    return;
end
names = {'x','k','wt','tdata','udata1','udata2','lat','psi','psiGround', ...
         'psi1_0','psi2_0','centerX'};
D = struct();
for jj = 1:numel(names)
    nm = names{jj};
    if evalin('base',['exist(''' nm ''',''var'')'])
        D.(nm) = evalin('base',nm);
    end
end
end

function idxSel = choose_collision_frames(t,C,separation,w1,w2,cfg)
Nt = numel(t);
if ~isempty(cfg.manualTimes)
    if numel(cfg.manualTimes) ~= 3
        error('cfg.manualTimes must be [tBefore,tCollision,tAfter].');
    end
    idxSel = arrayfun(@(tt) nearest_index(t,tt),cfg.manualTimes);
    return;
end

% First major local maximum rather than an arbitrary late radiation peak.
peaks = find(C(2:end-1)>=C(1:end-2) & C(2:end-1)>=C(3:end))+1;
peaks = peaks(C(peaks)>=cfg.majorPeakFraction*max(C));
if isempty(peaks)
    [~,ic] = max(C);
else
    ic = peaks(1);
end

clusterThr = cfg.collisionClusterFraction*C(ic);
left = ic;
while left > 1 && C(left-1) >= clusterThr
    left = left-1;
end
right = ic;
while right < Nt && C(right+1) >= clusterThr
    right = right+1;
end

quietThr = cfg.quietOverlapFraction*C(ic);
sepOK = separation > cfg.separationWidthFactor*(w1+w2);

candBefore = find((1:Nt)<left & C<=quietThr & sepOK,1,'last');
if isempty(candBefore)
    candBefore = max(1,left-cfg.selectionMarginFrames);
end
ib = max(1,candBefore-cfg.selectionMarginFrames);

ia = [];
for jj = right+1:Nt-cfg.afterHoldFrames+1
    rr = jj:jj+cfg.afterHoldFrames-1;
    if all(C(rr)<=quietThr) && all(sepOK(rr))
        ia = min(Nt,jj+cfg.selectionMarginFrames);
        break;
    end
end
if isempty(ia)
    ia = min(Nt,right+max(cfg.selectionMarginFrames,round(0.03*Nt)));
end

if ib >= ic
    ib = max(1,ic-max(5,round(0.05*Nt)));
end
if ia <= ic
    ia = min(Nt,ic+max(5,round(0.05*Nt)));
end
idxSel = [ib,ic,ia];
end

function R = bloch_project_component(u,x,t,lat,xc,cfg,doReconstruct)
% Cell-resolved Bloch transform on an integer number of lattice cells.
% The transformation is unitary inside the crop.  Therefore, summing all
% discrete cell bands exactly recovers the norm in the crop.

u = u(:);
N = numel(x);
dx = mean(diff(x));
a = lat.a;
Npc = round(a/dx);
M = cfg.bandWindowCells;
maxCells = floor(N/Npc);
M = min(M,maxCells);

[~,icenter] = min(abs(x-xc));
centerCell = floor((icenter-1)/Npc);
startCell = centerCell-floor(M/2);
startCell = max(0,min(maxCells-M,startCell));
startIdx = 1+startCell*Npc;
idx = startIdx:startIdx+M*Npc-1;

Ucell = reshape(u(idx),Npc,M);
Chi = fft(Ucell,[],2)/sqrt(M);

if mod(M,2)==0
    ell = [0:M/2-1,-M/2:-1];
else
    ell = [0:(M-1)/2,-(M-1)/2:-1];
end
klist = ell*(2*pi/(M*a));
xi = (0:Npc-1).'*dx;

% Fourier-grid Hamiltonian for the periodic part u_{n,k}(xi).
if mod(Npc,2)==0
    gind = [0:Npc/2-1,-Npc/2:-1].';
else
    gind = [0:(Npc-1)/2,-(Npc-1)/2:-1].';
end
G = gind*(2*pi/a);
F = fft(eye(Npc),[],1)/sqrt(Npc);
Vcell = external_potential(x(idx(1:Npc)),t,lat);

coeff = zeros(Npc,M);
allEval = zeros(Npc,M);
if doReconstruct
    nrec = min(cfg.nBandsReconstruct,Npc);
    ChiRec = zeros(Npc,M,nrec);
else
    nrec = 0;
    ChiRec = [];
end

for ik = 1:M
    kk = klist(ik);
    Hk = F' * diag(0.5*(G+kk).^2) * F + diag(Vcell);
    Hk = 0.5*(Hk+Hk');
    [Vec,Eval] = eig(Hk,'vector');
    [Eval,ord] = sort(real(Eval),'ascend');
    Vec = Vec(:,ord);
    allEval(:,ik) = Eval;

    periodicPart = exp(-1i*kk*xi).*Chi(:,ik);
    coeff(:,ik) = Vec'*periodicPart;

    for nb = 1:nrec
        pnb = Vec(:,nb)*coeff(nb,ik);
        ChiRec(:,ik,nb) = exp(1i*kk*xi).*pnb;
    end
end

normTotal = real(dx*sum(abs(u).^2));
normCrop = real(dx*sum(abs(Ucell(:)).^2));
inside = normCrop/(normTotal+eps);
popInside = dx*sum(abs(coeff).^2,2)/(normCrop+eps);
closureInside = sum(popInside);

ntrack = min(cfg.nBandsTrack,Npc);
popGlobal = inside*popInside(1:ntrack);
higherGlobal = inside*sum(popInside(ntrack+1:end));
outsideSpatial = max(0,1-inside);

reconstruction = zeros(N,nrec);
for nb = 1:nrec
    Urec = ifft(ChiRec(:,:,nb),[],2)*sqrt(M);
    tmp = zeros(N,1);
    tmp(idx) = Urec(:);
    reconstruction(:,nb) = tmp;
end

R = struct();
R.indexCrop = idx;
R.xCrop = x(idx);
R.klist = klist(:);
R.eigenvalues = allEval.';
R.populationInsideAll = popInside;
R.populationGlobal = popGlobal;
R.higherGlobal = higherGlobal;
R.insideSpatial = inside;
R.outsideSpatial = outsideSpatial;
R.closureInside = closureInside;
R.reconstruction = reconstruction;
R.Vcell = Vcell;
end

function Bands = instantaneous_band_diagrams(x,t,u1,u2,xc,lat,cfg)
dx = mean(diff(x));
a = lat.a;
Npc = round(a/dx);
N = numel(x);
maxCells = floor(N/Npc);
[~,icenter] = min(abs(x-xc));
cellId = floor((icenter-1)/Npc);
cellId = max(0,min(maxCells-1,cellId));
idx = 1+cellId*Npc:(cellId+1)*Npc;
xCell = x(idx);

Vbare = external_potential(xCell,t,lat);
r1 = abs(u1(idx)).^2;
r2 = abs(u2(idx)).^2;
Vcross = Vbare+lat.g12*r1;
Vfull = Vcross+lat.g22*r2;

[kx,Ebare] = bands_from_grid_cell(Vbare,a,dx,cfg.bandPlotNk);
[~,Ecross] = bands_from_grid_cell(Vcross,a,dx,cfg.bandPlotNk);
[~,Efull] = bands_from_grid_cell(Vfull,a,dx,cfg.bandPlotNk);

Bands = struct();
Bands.kx = kx;
Bands.bare = Ebare;
Bands.cross = Ecross;
Bands.full = Efull;
Bands.Vbare = Vbare;
Bands.Vcross = Vcross;
Bands.Vfull = Vfull;
Bands.xCell = xCell;
Bands.gapBare = band_gap_12(Ebare);
Bands.gapCross = band_gap_12(Ecross);
Bands.gapFull = band_gap_12(Efull);
end

function [kx,E] = bands_from_grid_cell(Vcell,a,dx,Nk)
Npc = numel(Vcell);
if mod(Npc,2)==0
    gind = [0:Npc/2-1,-Npc/2:-1].';
else
    gind = [0:(Npc-1)/2,-(Npc-1)/2:-1].';
end
G = gind*(2*pi/a);
F = fft(eye(Npc),[],1)/sqrt(Npc);
kx = linspace(-pi/a,pi/a,Nk).';
E = zeros(Nk,Npc);
for ik = 1:Nk
    H = F'*diag(0.5*(G+kx(ik)).^2)*F+diag(Vcell(:));
    ev = sort(real(eig(0.5*(H+H'))),'ascend');
    E(ik,:) = ev.';
end
% dx is part of the grid definition but the orthonormal Fourier grid has
% Euclidean normalization; no extra factor is required in the eigenvalues.
if dx <= 0 %#ok<UNRCH>
    error('Invalid dx.');
end
end

function [phi,info] = imaginary_time_fixed_norm(seed,Vbase,g,k,wt,targetN,cfg)
u = real(seed(:));
u = normalize_to_norm(u,targetN,wt);
EkHalf = exp(-cfg.imagDt*(k.^2)/4);
err = inf;
for it = 1:cfg.imagMaxIter
    old = u;
    u = ifft(EkHalf.*fft(u));
    u = exp(-cfg.imagDt*(Vbase+g*abs(u).^2)).*u;
    u = ifft(EkHalf.*fft(u));
    u = real(u);
    u = normalize_to_norm(u,targetN,wt);
    err = norm(u-old)/(norm(old)+eps);
    if err < cfg.imagTol
        break;
    end
end
phi = real_gauge_seed(u);
mu = stationary_mu(phi,Vbase,g,k,wt);
res = stationary_residual(phi,mu,Vbase,g,k);
info = struct();
info.iter = it;
info.error = err;
info.mu = mu;
info.residual = max(abs(res));
info.nodeCount = count_real_nodes(phi,cfg.nodeAmplitudeFraction);
info.valid = info.residual < max(1e-6,10*cfg.newtonTol);
end

function [bestPhi,bestInfo] = best_excited_branch(seeds,uTarget,Vbase,g,Tmat,k,wt, ...
    targetN,x,groundNodes,cfg)
bestPhi = [];
bestInfo = empty_branch_info();
bestScore = -inf;
for is = 1:numel(seeds)
    seed = real(seeds{is}(:));
    if max(abs(seed)) < 1e-12
        continue;
    end
    seed = normalize_to_norm(seed,targetN,wt);
    mu0 = stationary_mu(seed,Vbase,g,k,wt);
    [phi,mu,infoN] = newton_fixed_norm(seed,mu0,Vbase,g,Tmat,k,wt,targetN,cfg);
    xc = density_center(x,abs(phi).^2,wt);
    nodes = count_core_nodes(phi,x,xc,cfg.coreHalfWidth,cfg.nodeAmplitudeFraction);
    Ftarget = state_fidelity(phi,uTarget,wt);
    valid = infoN.residual < max(1e-6,10*cfg.newtonTol) && ...
        nodes >= groundNodes+cfg.excitedNodeExcess;
    score = 5*double(valid)+Ftarget-0.05*log10(infoN.residual+1e-16);
    if score > bestScore
        bestScore = score;
        bestPhi = phi;
        bestInfo = infoN;
        bestInfo.mu = mu;
        bestInfo.nodeCount = nodes;
        bestInfo.fidelityToTarget = Ftarget;
        bestInfo.valid = valid;
        bestInfo.seedIndex = is;
    end
end
if isempty(bestPhi)
    bestPhi = zeros(size(uTarget));
    bestInfo = empty_branch_info();
end
end

function [u,mu,info] = newton_fixed_norm(seed,mu,Vbase,g,Tmat,k,wt,targetN,cfg)
u = real(seed(:));
u = normalize_to_norm(u,targetN,wt);
N = numel(u);
err = inf;
for it = 1:cfg.newtonMaxIter
    R = Tmat*u+(Vbase-mu+g*u.^2).*u;
    C = real(sum(wt.*u.^2))-targetN;
    err = max(max(abs(R)),abs(C));
    if err < cfg.newtonTol
        break;
    end
    J = Tmat+diag(Vbase-mu+3*g*u.^2);
    Aug = [J,-u;(2*wt.*u).',0];
    rhs = [-R;-C];
    step = Aug\rhs;
    du = step(1:N);
    dmu = step(N+1);

    alpha = 1;
    accepted = false;
    for ls = 1:cfg.lineSearchMax
        un = u+alpha*du;
        mun = mu+alpha*dmu;
        Rn = Tmat*un+(Vbase-mun+g*un.^2).*un;
        Cn = real(sum(wt.*un.^2))-targetN;
        errn = max(max(abs(Rn)),abs(Cn));
        if errn < err || alpha < 1e-5
            accepted = true;
            break;
        end
        alpha = alpha/2;
    end
    if ~accepted
        break;
    end
    u = un;
    mu = mun;
end
u = real_gauge_seed(u);
res = stationary_residual(u,mu,Vbase,g,k);
info = struct();
info.iter = it;
info.error = err;
info.residual = max(abs(res));
info.valid = info.residual < max(1e-6,10*cfg.newtonTol);
info.nodeCount = count_real_nodes(u,cfg.nodeAmplitudeFraction);
info.fidelityToTarget = NaN;
info.seedIndex = NaN;
end

function val = frozen_current_residual(u,Vbase,g,k,wt)
mu = stationary_mu(u,Vbase,g,k,wt);
R = stationary_residual(u,mu,Vbase,g,k);
val = max(abs(R));
end

function mu = stationary_mu(u,Vbase,g,k,wt)
Tu = ifft(0.5*k.^2.*fft(u));
N = real(sum(wt.*abs(u).^2));
mu = real(sum(wt.*conj(u).*(Tu+(Vbase+g*abs(u).^2).*u)))/(N+eps);
end

function R = stationary_residual(u,mu,Vbase,g,k)
Tu = ifft(0.5*k.^2.*fft(u));
R = Tu+(Vbase-mu+g*abs(u).^2).*u;
end

function E = nonlinear_energy(u,Vbase,g,k,wt)
ux = ifft(1i*k.*fft(u));
E = real(sum(wt.*(0.5*abs(ux).^2+Vbase.*abs(u).^2+0.5*g*abs(u).^4)));
end

function Tmat = build_kinetic_matrix(k)
N = numel(k);
I = eye(N);
Tmat = real(ifft((0.5*k.^2).*fft(I,[],1),[],1));
Tmat = 0.5*(Tmat+Tmat');
end

function u = remove_mean_flow(u,x,xc,pmean)
u = u(:).*exp(-1i*pmean*(x(:)-xc));
end

function p = mean_momentum(u,k,wt)
ux = ifft(1i*k.*fft(u));
N = real(sum(wt.*abs(u).^2));
p = real(sum(wt.*conj(u).*(-1i*ux)))/(N+eps);
end

function F = state_fidelity(u,v,wt)
nu = real(sum(wt.*abs(u).^2));
nv = real(sum(wt.*abs(v).^2));
F = abs(sum(wt.*conj(u).*v))^2/(nu*nv+eps);
F = min(max(real(F),0),1);
end

function u = real_gauge_seed(u)
u = u(:);
[~,im] = max(abs(u));
if max(abs(u)) < 1e-14
    return;
end
u = u*exp(-1i*angle(u(im)));
u = real(u);
if u(im) < 0
    u = -u;
end
end

function u = normalize_to_norm(u,targetN,wt)
n = real(sum(wt.*abs(u).^2));
if n < 1e-16
    error('Cannot normalize a zero seed.');
end
u = u*sqrt(targetN/n);
end

function uShift = fft_shift_state(u,delta,k)
uShift = ifft(fft(u(:)).*exp(-1i*k(:)*delta));
end

function V = external_potential(x,t,lat)
V = -lat.p1*cos(pi*x/lat.d1).^2 ...
    -lat.p2*cos(pi*x/lat.d2-lat.nu*t).^2;
end

function xc = density_center(x,rho,wt)
xc = real(sum(wt.*x.*rho)/(sum(wt.*rho)+eps));
end

function w = density_width(x,rho,wt,xc)
w = sqrt(max(real(sum(wt.*(x-xc).^2.*rho)/(sum(wt.*rho)+eps)),0));
end

function n = count_core_nodes(u,x,xc,halfWidth,ampFrac)
mask = abs(x-xc)<=halfWidth;
u = u(mask);
if isempty(u) || max(abs(u)) < 1e-14
    n = 0;
    return;
end
u = real_gauge_seed(u);
keep = abs(u)>=ampFrac*max(abs(u));
idx = find(keep);
if numel(idx)<2
    n = 0;
    return;
end
% Split into amplitude lobes.  A sign reversal between neighboring lobes
% is counted as one node; weak radiative tails are excluded by keep.
breaks = [1;find(diff(idx)>1)+1;numel(idx)+1];
signs = zeros(numel(breaks)-1,1);
for jj = 1:numel(signs)
    seg = idx(breaks(jj):breaks(jj+1)-1);
    signs(jj) = sign(sum(u(seg)));
    if signs(jj)==0
        signs(jj)=1;
    end
end
n = sum(signs(1:end-1).*signs(2:end)<0);
end

function n = count_real_nodes(u,ampFrac)
u = real_gauge_seed(u);
keep = abs(u)>=ampFrac*max(abs(u));
idx = find(keep);
if numel(idx)<2
    n = 0;
    return;
end
breaks = [1;find(diff(idx)>1)+1;numel(idx)+1];
s = zeros(numel(breaks)-1,1);
for jj = 1:numel(s)
    seg = idx(breaks(jj):breaks(jj+1)-1);
    s(jj)=sign(sum(u(seg)));
    if s(jj)==0, s(jj)=1; end
end
n = sum(s(1:end-1).*s(2:end)<0);
end

function gap = band_gap_12(E)
if size(E,2)<2
    gap = NaN;
else
    gap = min(E(:,2))-max(E(:,1));
end
end

function idx = nearest_index(v,val)
[~,idx] = min(abs(v-val));
end

function S = empty_frozen_result()
S = struct('time',NaN,'index',NaN,'uRest',[],'ground',[],'excited',[], ...
    'Fg',NaN,'Fe',NaN,'Sge',NaN,'groundInfo',empty_branch_info(), ...
    'excitedInfo',empty_branch_info(),'currentResidual',NaN, ...
    'currentEnergy',NaN,'groundEnergy',NaN,'excitedEnergy',NaN);
end

function S = empty_branch_info()
S = struct('iter',0,'error',inf,'mu',NaN,'residual',inf,'nodeCount',0, ...
    'valid',false,'fidelityToTarget',NaN,'seedIndex',NaN);
end
